import numpy as np
from scipy.optimize import curve_fit

data = []
with open('/app/graphene.dat', 'r') as f:
    for line in f:
        line = line.strip()
        if not line: continue
        parts = line.split()
        if len(parts) < 2: continue
        data.append((float(parts[0].replace(',','.')), float(parts[1].replace(',','.'))))
data = np.array(data)
order = np.argsort(data[:,0])
xs, ys = data[order,0], data[order,1]

def L4(x,x0,g,a,c): return a*g*g/((x-x0)**2+g*g)+c
def L5(x,x0,g,a,m,b): return a*g*g/((x-x0)**2+g*g)+m*x+b

def do(name, model, x, y, p0):
    try:
        popt,pcov = curve_fit(model, x, y, p0=p0, maxfev=500000)
        r = y - model(x,*popt)
        rms = np.sqrt(np.mean(r**2))
        return popt, rms, None
    except Exception as e:
        return None, None, repr(e)

print("===== G PEAK =====")
for (lo,hi) in [(17000,22000),(18000,21000),(18500,20500)]:
    m=(xs>lo)&(xs<hi); xg,yg=xs[m],ys[m]
    print(f"Window [{lo},{hi}], npts={len(xg)}")
    p,rms,err=do('L4',L4,xg,yg,[19140,400,67000,13000])
    if err: print(f"  L4 ERR: {err}")
    else: print(f"  L4: x0={p[0]:.1f} g={abs(p[1]):.1f} amp={p[2]:.1f} off={p[3]:.1f} amp+off={p[2]+p[3]:.1f} RMS={rms:.1f}")
    p,rms,err=do('L5',L5,xg,yg,[19140,400,67000,-1.0,16000])
    if err: print(f"  L5 ERR: {err}")
    else:
        off=p[3]*p[0]+p[4]
        print(f"  L5: x0={p[0]:.1f} g={abs(p[1]):.1f} amp={p[2]:.1f} slope={p[3]:.3f} off@x0={off:.1f} amp+off@x0={p[2]+off:.1f} RMS={rms:.1f}")

print("\n===== 2D PEAK =====")
for (lo,hi) in [(30000,37000),(31500,35500),(32000,35000)]:
    m=(xs>lo)&(xs<hi); x2,y2=xs[m],ys[m]
    print(f"Window [{lo},{hi}], npts={len(x2)}")
    p,rms,err=do('L4',L4,x2,y2,[33245,900,1800,19300])
    if err: print(f"  L4 ERR: {err}")
    else: print(f"  L4: x0={p[0]:.1f} g={abs(p[1]):.1f} amp={p[2]:.1f} off={p[3]:.1f} amp+off={p[2]+p[3]:.1f} RMS={rms:.1f}")
    p,rms,err=do('L5',L5,x2,y2,[33245,900,1800,0.2,13000])
    if err: print(f"  L5 ERR: {err}")
    else:
        off=p[3]*p[0]+p[4]
        print(f"  L5: x0={p[0]:.1f} g={abs(p[1]):.1f} amp={p[2]:.1f} slope={p[3]:.3f} off@x0={off:.1f} amp+off@x0={p[2]+off:.1f} RMS={rms:.1f}")
